import { _decorator, Animation, Component, Label, Layers, Material, math, Node, Size, sp, Sprite, Tween, tween, UITransform, v2, v3, Vec3 } from 'cc';
import { PoolMember, PoolType } from '../Pool/PoolMember';
import { Thing } from './Thing';
import Ulis from '../Misc/Ulis';
import { room } from './Room';
import { ui } from '../Manager/UI';
import { sm, SoundType } from '../Manager/SoundManager';
import { World } from '../Manager/World';
import { Cloud } from '../Misc/Cloud';
const { ccclass, property } = _decorator;

@ccclass('Slot')
export class Slot extends PoolMember {
    start() {

    }

    @property
    thingType: number = -1
    thingys: Sprite[] = [];
    outlines: Sprite[] = [];
    frame: Sprite = null
    @property(Thing)
    thing: Thing = null
    label: Label = null
    moveTween: Tween<any> = null
    amount: number = 0
    maxAmount: number = 0
    scaleTween: Tween<any> = null
    moving: boolean = false
    materials: Material[] = [];
    anim: Animation = null;
    hightlighted: boolean = false
    things: Thing[] = [];
    ticks: Node[] = [];
    added: number = 0;

    init() {
        let sps = this.node.getComponentsInChildren(Sprite);
        this.frame = sps[0];
        this.outlines = [sps[1], sps[2], sps[3]];
        this.thingys = [sps[4], sps[5], sps[6]];
        // this.material = this.frame.material;
        // this.anim = this.node.getComponentInChildren(Animation);
    }

    initSlot() {
        let sps = this.node.getComponentsInChildren(Sprite);
        this.frame = sps[0];
        this.outlines = [sps[1], sps[2], sps[3]];
        this.thingys = [sps[4], sps[5], sps[6]];
        this.materials = this.thingys.map(thingy => thingy.material);
        // this.material = this.frame.material;
        this.anim = this.node.getComponent(Animation);
        this.ticks = [sps[7].node, sps[8].node, sps[9].node];
        this.ticks.forEach((tick) => {
            tick.active = false;
        });
    }

    index: number = 0

    swapIndex(slot: Slot) {
        slot.setBoxThing(this.thing, true);
        this.onDespawnThing();
    }

    moveToPos(pos: Vec3, pos2: Vec3) {
        const lpos = this.node.position.clone();
        const t = this;
        let time = pos.clone().subtract(lpos).length() / 3000;
        this.moveTween?.stop();
        this.moveTween = tween({})
        .to(time, {}, {
            onUpdate(target, ratio) {
                if(ui.width < ui.height) {
                    t.node.position = Vec3.lerp(v3(), lpos, pos, ratio);
                } else {
                    t.node.position = Vec3.lerp(v3(), lpos, pos2, ratio);
                }
            },
        }).start();
    }

    setLabel(amount: number) {
        this.label = this.node.getComponentInChildren(Label);
        this.amount = amount;        
        this.maxAmount = amount;
        // this.label.node.active = false;
        this.label.string = "x" + amount;
    }

    decreaseLabel() {
        this.amount -= 1;
        this.label.string = "x" + this.amount;
    }

    setThingFrame(thing: Thing) {
        this.thingType = thing.thingType;
        this.thing = thing;

        let size = thing.getComponent(UITransform).contentSize.clone();
        let thingScale = thing.node.worldScale.clone();
        let t = v2(size.width*thingScale.x, size.height*thingScale.y);
        
        let frameSize = this.thingys[0].getComponent(UITransform).contentSize.clone();
        frameSize = new Size(45, 45);
        let thingyScale = this.thingys[0].node.worldScale.clone();
        let ty = v2(frameSize.width*thingyScale.x, frameSize.height*thingyScale.y);

        let mul = 0.9;
        let ratio2 = v2(t.x/ty.x, t.y/ty.y);
        let ratio = 1/Math.max(ratio2.x, ratio2.y)*mul;

        let thingySize = v2(t.x/thingyScale.x*ratio, t.y/thingyScale.y*ratio);
        this.thingys.forEach((thingy, i) => {
                thingy.node.getComponent(UITransform).contentSize.set(thingySize.x, thingySize.y);
                thingy.spriteFrame = thing.frame;
                // thingy.node.position = v3(0, 8, 0);
                this.outlines[i].node.getComponent(UITransform)
                .contentSize.set(thingySize.x*1.1, thingySize.y*1.1);
                this.outlines[i].spriteFrame = thing.frame;

        });
    }

    movingNodes: Node[] = [];
    setSlotThing(thing: Thing, linear: boolean = false, callback: Function = null) {
        if(room.lose) return;
        this.moving = true;

        if(!thing) {
            console.log("no thing");
            
        }

        let sk = thing.node.parent.parent.getComponent(sp.Skeleton)
        console.log(thing.node.parent.parent.name);
        
        if(sk) {
            sk.setAnimation(0, "3-takeitem-done", true);
        }
        this.movingNodes.push(thing.node);

        // this.offHightlight();
        let star = World.ins.poolManager.spawnType<Cloud>(PoolType.StarVFX);
        star.node.parent = room.vfxNode;
        star.node.position = v3(0, 0, 0);
        star.init();
        star.target = thing.node;
        
        thing.box = this;
        Ulis.addToParent(thing.node, this.node);
        thing.setUpLayer();    
        this.thingType = thing.thingType;
        this.thing = thing;

        let size = thing.getComponent(UITransform).contentSize.clone();
        let thingScale = thing.node.worldScale.clone();
        let t = v2(size.width*thingScale.x, size.height*thingScale.y);
        
        let frameSize = this.thingys[0].getComponent(UITransform).contentSize.clone();
        // frameSize = new Size(40, 50);
        let thingyScale = this.thingys[0].node.worldScale.clone();
        let ty = v2(frameSize.width*thingyScale.x, frameSize.height*thingyScale.y);


        let mul = 1;
        let ratio2 = v2(t.x/ty.x, t.y/ty.y);
        let ratio = 1/Math.max(ratio2.x, ratio2.y)*mul;
        let scale = thing.node.scale.clone().multiplyScalar(ratio);

        let up = 0;
        let dTime = up / 500;
        dTime = ui.width < ui.height ? dTime : dTime*0.35;
        let pos = this.node.worldPosition.clone();
        let s = thing.node.worldPosition.clone();
        const src = s.clone().add(v3(0, up, 0));
        let local = thing.node.parent.inverseTransformPoint(v3(), src);
        let dir = pos.clone().subtract(src);
        let time = dir.length() / 3000;
        time = ui.width < ui.height ? time : time*0.35;
        
        let temp = v3();
        let des = v3();
        const slot = this.thingys[this.added].node;
        // const slot = (this.thingys[this.added] || this.thingys[0]).node;
        let tick = this.ticks[this.added];
        let before = this.added + 0;
        this.added += 1;
        let delay = 0.0;
        thing.onHightlight();
        if(linear ) {
            let height = 100;
            time = Vec3.distance(s, slot.worldPosition) / 3000;
            time = ui.width < ui.height ? time : time*0.35;
            tween(thing.node)
            .call(() => {
                thing.offAnim();
            })
            .to(time, {scale: scale, eulerAngles: v3()}, {easing: 'smooth',
                onUpdate(target, ratio) {
                    des = slot.worldPosition.clone();  
                    temp = Ulis.lerpParabola(s, des, ratio, height, 0.5);
                    thing.node.worldPosition = temp;
                },
            })
            .call(() => {
                setTimeout(() => {
                    star.target = null;                    
                }, 200);
                thing.node.worldPosition = slot.worldPosition.clone();
                thing.node.layer = Math.pow(2, Layers.nameToLayer("UI_2D"));
                this.moving = false;
                // room.checkLose();
                tick.active = true;
                thing.node.destroy();
                if(before == this.added - 1 && this.added == this.amount) {
                    room.onFull(this);
                }
            })
            .start();

        } else {
            if(thing.firstIndex >= 0) {
                this.moving = false;
                tick.active = true;
                thing.node.destroy();
                if(before == this.added - 1 && this.added == this.amount) {
                    room.onFull(this);
                }
            } else {

                if(thing.sfx) {
                    sm.playSound(thing.audio);
                }

                let height = 300;
                let t = this;
                tween(thing.node)
                .to(dTime, {position: local}, {easing: 'smooth'})
                .delay(delay)
                .call(() => {
                    thing.offAnim();
                })
                .to(time, {scale: scale, eulerAngles: v3()}, {easing: 'smooth',
                    onUpdate(target, ratio) {
                        t.moving = true;
                        des = slot.worldPosition.clone();  
                        temp = Ulis.lerpParabola(src, des, ratio, height, 0.5);
                        thing.node.worldPosition = temp;
                    },
                })
                .call(() => {
                    sm.playSound(SoundType.LandRight)
                    setTimeout(() => {
                        star.target = null;                    
                    }, 200);
                    // thing.node.worldPosition = slot.worldPosition.clone();
                    // thing.node.layer = Math.pow(2, Layers.nameToLayer("UI_2D"));
                    this.moving = false;
                    // room.checkLose();
                    tick.active = true;
                    callback && callback();
                    thing.node.destroy();
                    // this.decreaseLabel();
                    if(before == this.added - 1 && this.added == this.amount) {
                        room.onFull(this);
                    }
                })
                .start();
            }

        }
    }


    setBoxThing(thing: Thing, linear: boolean = false) {
        if(room.lose) return;
        this.moving = true;
        if(thing.box) {
            thing.box.onDespawnThing();
        }
        let sk = thing.node.parent.parent.getComponent(sp.Skeleton)
        console.log(thing.node.parent.parent.name);
        
        if(sk) {
            sk.setAnimation(0, "3-takeitem-done", true);
        }
        thing.box = this;
        Ulis.addToParent(thing.node, this.node);
        thing.setUpLayer();         
        this.thingType = thing.thingType;
        this.thing = thing;

        let size = thing.getComponent(UITransform).contentSize.clone();
        let thingScale = thing.node.worldScale.clone();
        let t = v2(size.width*thingScale.x, size.height*thingScale.y);
        
        let frameSize = this.frame.getComponent(UITransform).contentSize.clone();
        let thingyScale = this.frame.node.worldScale.clone();
        let ty = v2(frameSize.width*thingyScale.x, frameSize.height*thingyScale.y);


        let mul = 0.9;
        let ratio2 = v2(t.x/ty.x, t.y/ty.y);
        let ratio = 1/Math.max(ratio2.x, ratio2.y)*mul;
        let scale = thing.node.scale.clone().multiplyScalar(ratio);
        if(linear) {
            let pos = this.node.worldPosition.clone();        
            const src = thing.node.worldPosition.clone();
            let dir = src.clone().subtract(pos.clone());
            let time = dir.length() / 3000;
            time = ui.width < ui.height ? time : time*0.35;
            let temp = v3();
            let des = v3();
            const slot = this;
            let delay = 0.2;
            let height = 0;
            this.moveTween?.stop();
            
            this.moveTween = tween(thing.node)
            .delay(delay)
            .to(time, {scale: scale}, {easing: 'smooth',
                onUpdate(target, ratio) {
                    des = slot.node.worldPosition.clone();  
                    temp = Ulis.lerpParabola(src, des, ratio, height, 0.5);
                    thing.node.worldPosition = temp;
                },
            })
            .call(() => {
                thing.node.layer = Math.pow(2, Layers.nameToLayer("UI_2D"));
                this.moving = false;
                thing.node.worldPosition = slot.node.worldPosition.clone();
                // room.checkTrippleBox(this);
                this.node.scale = v3(1, 1, 1);
                thing.node.position = v3(0, 0, 0);
                room.rearrangeBoxes(room.boxes);
                // room.checkLose();
            })
            .start();

        } else {
            
            if(thing.sfx) {
                sm.playSound(thing.audio);
            }

            let up = 0;
            let dTime = up / 500;
            dTime = ui.width < ui.height ? dTime : dTime*0.35;
            let pos = this.node.worldPosition.clone();
            let s = thing.node.worldPosition.clone();
            const src = s.clone().add(v3(0, up, 0));
            let local = thing.node.parent.inverseTransformPoint(v3(), src);
            let dir = pos.clone().subtract(src);
            let time = dir.length() / 3000;
            time = ui.width < ui.height ? time : time*0.35;
            
            let temp = v3();
            let des = v3();
            const slot = this;
            let height = 300;
            let delay = 0.0;
            thing.onHightlight();
            this.moveTween?.stop();
            if(thing.firstIndex >= 0) {
                thing.offAnim();
                thing.node.worldPosition = slot.node.worldPosition.clone();
                thing.node.layer = Math.pow(2, Layers.nameToLayer("UI_2D"));
                thing.node.scale = scale;
                thing.node.eulerAngles = v3();
                this.moving = false;
                this.onMoved();                
            } else {
                this.moveTween = tween(thing.node)
                .to(dTime, {position: local}, {easing: 'smooth'})
                .delay(delay)
                .call(() => {
                    thing.offAnim();
                })
                .to(time, {scale: scale, eulerAngles: v3()}, {easing: 'smooth',
                    onUpdate(target, ratio) {
                        des = slot.node.worldPosition.clone();  
                        temp = Ulis.lerpParabola(src, des, ratio, height, 0.5);
                        thing.node.worldPosition = temp;
                    },
                })
                .call(() => {
                    sm.playSound(SoundType.LandFail);
                    thing.node.worldPosition = slot.node.worldPosition.clone();
                    thing.node.layer = Math.pow(2, Layers.nameToLayer("UI_2D"));
                    thing.scaleSize(false);
                    this.moving = false;
                    this.onMoved();
                    room.moved();
                })
                .start();
                
            }
        }
    }

    onSlot(thing: Thing) {
        this.decreaseLabel();
        this.added++;
        thing.flicker();
        thing.slot = this;
        thing.setUpLayer();
        this.things.push(thing);
        if(this.things.length == 3) {
            let movingNode = this.things.map(t => t.node);
            this.things.forEach(t => {
                t.offHightlight();
                t.offAnim();
                this.setSlotThing(t, false, () => {
                    movingNode = movingNode.filter(n => n != t.node);
                    if(movingNode.length == 0) {
                        this.onThingMoved();
                    }
                })
            });
            this.things = [];
        }
    }

    onThingMoved() {
        console.log("moved");
        
        if(!this.moving && this.amount == 0) {
            room.onFull(this);
        } else {
            sm.playSound(SoundType.Done);
        }
    }

    onMoved() {
    }

    onDespawnThing() {
        if(this.thing) {
            this.thing.box = null;
        }
        this.thingType = -1;
        this.thing = null;
    }

    onHightlight() {
        this.frame.enabled = true;
        this.anim.stop();
        this.materials.forEach((material, i) => {
            // material.setProperty("useOutline", 1);
            // material.setProperty("alpha", 1);
            // material.setProperty("useOutline", 1, 1);
            // material.setProperty("alpha", 1, 1);
            // this.thingys[i].material = material;
        })
        this.thingys.forEach((thingy, i) => {
            thingy.node.scale = v3(1, 1, 1).multiplyScalar(1);
            this.outlines[i].node.scale = v3(1, 1, 1).multiplyScalar(1);
        });

        this.hightlighted = true;
    }

    offHightlight() {
        this.frame.enabled = true;
        this.anim.stop();
        this.thingys.forEach((thingy, i) => {
            thingy.node.scale = v3(1, 1, 1).multiplyScalar(1);
            this.outlines[i].node.scale = v3(1, 1, 1).multiplyScalar(1);
        });

        this.materials.forEach((material, i) => {
            // material.setProperty("useOutline", 0);
            // material.setProperty("useOutline", 0, 1);
            // this.thingys[i].material = material;
        })

        this.hightlighted = false;
    }

    flicker() {
        this.onHightlight();
        this.anim.play();
    }

    update(deltaTime: number) {
        
    }
}


